"use client";import {FormEvent,useState} from "react";
export function InquiryForm({slug,sold}:{slug:string;sold:boolean}){const [state,setState]=useState("");const [sent,setSent]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setState("Sending your request…");const form=new FormData(e.currentTarget);const body=Object.fromEntries(form);const response=await fetch(`/api/inquiries/${slug}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const data=await response.json();setState(response.ok?data.next_step:data.detail||"Please review the details and try again.");if(response.ok){setSent(true);e.currentTarget.reset()}}return <form onSubmit={submit} className="formCard inquiryForm"><div className="formRow"><label><span>What would you like to do?</span><select name="kind" defaultValue={sold?"inquiry":"viewing"}><option value="viewing">Arrange a viewing</option><option value="inquiry">Ask a question</option><option value="offer">Discuss an offer</option></select></label><label><span>Preferred time</span><input type="datetime-local" name="preferred_at"/></label></div><div className="formRow"><label><span>Your name</span><input required name="name" autoComplete="name" placeholder="Full name"/></label><label><span>Phone number</span><input required name="phone" autoComplete="tel" placeholder="+234"/></label></div><label><span>Email address</span><input required type="email" name="email" autoComplete="email" placeholder="you@example.com"/></label><label><span>Offer amount <small>optional</small></span><input type="number" min="0" name="offer_amount" placeholder="₦"/></label><label><span>Anything we should know?</span><textarea name="message" rows={3} placeholder="Questions, timing, or context…"/></label><label className="consent"><input required type="checkbox" name="consent" value="true"/><span>I agree that {"the dealer"} may contact me about this request.</span></label><button className="button light full">Send private request <span>↗</span></button>{state&&<p className={sent?"formSuccess":"formMessage"} role="status">{state}</p>}</form>}
